def log(kind, x):
    with open(LOG, 'a') as f: f.write(f"{datetime.datetime.now().isoformat(timespec='seconds')} {kind} {str(x)[:300]}\n")
def safe(p):
    q = os.path.realpath(p if os.path.isabs(p) else os.path.join(ROOT, p))
