@mcp.tool()
def list_dir(path: str = '.') -> str:
    """List a folder under /home/lhc/fantasy (path is relative to it)."""
    q = safe(path); log('ls', path); out = []
    for n in sorted(os.listdir(q)):
        fp = os.path.join(q, n); s = os.stat(fp)
        out.append(f"{'d' if os.path.isdir(fp) else '-'} {s.st_size:>9} {datetime.datetime.fromtimestamp(s.st_mtime):%m-%d %H:%M} {n}")
    return '\n'.join(out) or '(empty)'
@mcp.tool()
def read_file(path: str, start: int = 1, lines: int = 400) -> str:
    """Read a text file under the fantasy folder. start = first line (1-based), lines = how many."""
    q = safe(path); log('read', f'{path}:{start}+{lines}')
    with open(q, encoding='utf-8', errors='replace') as f: L = f.readlines()
    return f"[{len(L)} lines]\n" + ''.join(f"{i+1}\t{l}" for i, l in enumerate(L[start-1:start-1+lines], start=start-1))
@mcp.tool()
def grep_file(path: str, pattern: str, context: int = 0, max_hits: int = 50) -> str:
    """Regex search inside one file; returns numbered lines with optional context."""
    q = safe(path); log('grep', f'{path}:{pattern}'); rx = re.compile(pattern)
    L = open(q, encoding='utf-8', errors='replace').read().split('\n'); out = []; n = 0
    for i, l in enumerate(L):
        if rx.search(l):
            n += 1
            if n > max_hits: out.append('...more'); break
            for j in range(max(0, i-context), min(len(L), i+context+1)): out.append(f"{j+1}\t{L[j]}")
            if context: out.append('--')
    return '\n'.join(out) or 'no match'
@mcp.tool()
def write_file(path: str, content: str) -> str:
    """Write a whole text file under the fantasy folder; the previous version is kept as .bak."""
    q = safe(path); log('write', f'{path} {len(content)}b')
    if os.path.exists(q): shutil.copy2(q, q + '.bak')
    os.makedirs(os.path.dirname(q), exist_ok=True)
    with open(q, 'w', encoding='utf-8') as f: f.write(content)
    return f'wrote {len(content)} chars to {path}'
@mcp.tool()
def replace_in_file(path: str, old: str, new: str, count: int = 1) -> str:
